import boto3,json
r='us-east-1'; vpc='vpc-0836d003a70f93405'; ec2=boto3.client('ec2',region_name=r)
existing=ec2.describe_instances(Filters=[{'Name':'tag:Name','Values':['infs3701-team-runtime-builder']},{'Name':'instance-state-name','Values':['pending','running','stopped','stopping']}])['Reservations']
if existing:
 print('EXISTING_BUILDER='+json.dumps([i['InstanceId'] for x in existing for i in x['Instances']]))
else:
 groups=ec2.describe_security_groups(Filters=[{'Name':'vpc-id','Values':[vpc]},{'Name':'group-name','Values':['infs3701-team-builder-sg']}])['SecurityGroups']
 sg=groups[0]['GroupId'] if groups else ec2.create_security_group(GroupName='infs3701-team-builder-sg',Description='Temporary runtime builder; no inbound access; no instance role',VpcId=vpc,TagSpecifications=[{'ResourceType':'security-group','Tags':[{'Key':'Project','Value':'infs3701-team'},{'Key':'Name','Value':'infs3701-team-builder-sg'}]}])['GroupId']
 ami='ami-0c230065b91270bc6'; image=ec2.describe_images(ImageIds=[ami])['Images'][0]
 out=ec2.run_instances(ImageId=ami,InstanceType='t3.micro',MinCount=1,MaxCount=1,NetworkInterfaces=[{'DeviceIndex':0,'SubnetId':'subnet-0567427f846712996','Groups':[sg],'AssociatePublicIpAddress':True}],BlockDeviceMappings=[{'DeviceName':image['RootDeviceName'],'Ebs':{'VolumeSize':8,'VolumeType':'gp3','Encrypted':True,'DeleteOnTermination':True}}],MetadataOptions={'HttpTokens':'required','HttpEndpoint':'enabled'},CreditSpecification={'CpuCredits':'standard'},UserData="#!/bin/bash\nset -euxo pipefail\nexec > >(tee -a /var/log/infs3701-runtime-build.log /dev/console) 2>&1\ndnf install -y python3.11 python3.11-pip\nmkdir -p /opt/infs3701/current /etc/infs3701\npython3.11 -m venv /opt/infs3701/venv\n/opt/infs3701/venv/bin/python -m pip install --upgrade pip\n/opt/infs3701/venv/bin/python -m pip install Flask boto3 gunicorn\n/opt/infs3701/venv/bin/python -m pip freeze > /opt/infs3701/runtime-requirements.lock\ncat > /opt/infs3701/current/app.py <<'PYAPP'\nimport os\nfrom flask import Flask, jsonify\napp=Flask(__name__)\n@app.after_request\ndef identify(response):\n response.headers['X-App-Instance']=os.getenv('APP_INSTANCE','unconfigured')\n return response\n@app.get('/health')\ndef health():\n return jsonify(status='ok',instance=os.getenv('APP_INSTANCE','unconfigured'),stage='infrastructure-only')\n@app.get('/')\ndef home():\n return '<h1>INFS3701 infrastructure ready</h1><p>Reading Tracker application has not been deployed here yet.</p>'\nPYAPP\ncat > /etc/systemd/system/infs3701-app.service <<'UNIT'\n[Unit]\nDescription=INFS3701 staged application runtime\nAfter=network-online.target\nWants=network-online.target\n[Service]\nUser=ec2-user\nWorkingDirectory=/opt/infs3701/current\nEnvironmentFile=-/etc/infs3701/app.env\nExecStart=/opt/infs3701/venv/bin/gunicorn --bind 0.0.0.0:8000 --workers 2 --access-logfile - --error-logfile - app:app\nRestart=on-failure\nRestartSec=3\n[Install]\nWantedBy=multi-user.target\nUNIT\nsystemctl daemon-reload\n/opt/infs3701/venv/bin/python -c 'import sys,flask,boto3,gunicorn; print(\"RUNTIME_IMPORTS_OK\",sys.version.split()[0])'\ncat /opt/infs3701/runtime-requirements.lock\nprintf 'INFS3701_RUNTIME_READY\\n'\n",TagSpecifications=[{'ResourceType':'instance','Tags':[{'Key':'Name','Value':'infs3701-team-runtime-builder'},{'Key':'Project','Value':'infs3701-team'},{'Key':'Purpose','Value':'runtime-build-no-IAM-role'}]},{'ResourceType':'volume','Tags':[{'Key':'Project','Value':'infs3701-team'}]}])
 print('BUILDER_CREATED='+json.dumps({'id':out['Instances'][0]['InstanceId'],'sg':sg,'iam_role':'none','inbound_rules':'none','encrypted_root':True}))
